(()=>{
'use strict';
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const pad=n=>String(n).padStart(2,'0');
const api=async(url,opt={})=>{const init={credentials:'same-origin',cache:'no-store',...opt};if(opt.body!=null)init.headers={'Content-Type':'application/json',...(opt.headers||{})};const r=await fetch(url,init);const p=await r.json().catch(()=>({success:false,message:'서버 응답 오류'}));if(!r.ok||p?.success===false)throw new Error(p?.message||`HTTP ${r.status}`);return p?.data??p};
const state={schedule:{startTime:'09:00',endTime:'18:00'},today:null};
function toast(msg){let t=$('#namoLiveToast');if(!t){t=document.createElement('div');t.id='namoLiveToast';Object.assign(t.style,{position:'fixed',left:'50%',bottom:'92px',transform:'translateX(-50%)',zIndex:'9999',background:'#16243a',color:'#fff',padding:'11px 15px',borderRadius:'12px',fontSize:'12px',fontWeight:'800',maxWidth:'calc(100% - 34px)',boxShadow:'0 10px 30px rgba(0,0,0,.18)',opacity:'0',transition:'.18s',pointerEvents:'none'});document.body.appendChild(t)}t.textContent=msg;t.style.opacity='1';clearTimeout(t._timer);t._timer=setTimeout(()=>t.style.opacity='0',2500)}
function safeDate(v){if(!v)return null;const s=String(v).slice(0,10);const m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return null;const d=new Date(Number(m[1]),Number(m[2])-1,Number(m[3]));return Number.isNaN(d.getTime())?null:d}
function time(v){if(!v)return'--:--';const d=new Date(v);return Number.isNaN(d.getTime())?'--:--':d.toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false})}
function mins(t){const m=String(t||'').match(/^(\d{2}):(\d{2})$/);return m?Number(m[1])*60+Number(m[2]):540}
function refreshScheduleLabels(){const a=state.schedule.startTime,b=state.schedule.endTime;const mini=$('.work-time .mini');if(mini)mini.textContent=`(${a} - ${b})`;const labels=$$('.progress-labels span');if(labels[0])labels[0].textContent=a;if(labels[1])labels[1].textContent=b;const inTime=$('#clockInTime');const outTime=$('#clockOutTime');if(inTime&&!state.today?.clockIn)inTime.textContent=a;if(outTime&&!state.today?.clockOut)outTime.textContent=b}
async function loadSchedule(){try{state.schedule=await api('/api/attendance/work-schedule');refreshScheduleLabels()}catch(_){refreshScheduleLabels()}}
function ensureScheduleEditor(){if($('#scheduleEditOverlay'))return;document.body.insertAdjacentHTML('beforeend',`<div class="schedule-edit-overlay" id="scheduleEditOverlay"><div class="schedule-edit-sheet"><div class="schedule-edit-head"><b>근무시간 설정</b><button class="schedule-edit-close" id="scheduleEditClose">×</button></div><div class="schedule-edit-card"><div class="schedule-edit-grid"><label>출근 기준시간<input type="time" id="scheduleStart" value="09:00"></label><label>퇴근 기준시간<input type="time" id="scheduleEnd" value="18:00"></label></div><div class="schedule-edit-note">변경한 시간은 이후 근무시간 표시와 지각 기준에 사용합니다. 과거 출퇴근 기록 시간은 변경하지 않습니다.</div><button class="schedule-edit-save" id="scheduleEditSave">저장</button></div></div></div>`);$('#scheduleEditClose').onclick=()=>$('#scheduleEditOverlay').classList.remove('open');$('#scheduleEditOverlay').onclick=e=>{if(e.target.id==='scheduleEditOverlay')e.currentTarget.classList.remove('open')};$('#scheduleEditSave').onclick=saveSchedule}
function openSchedule(){ensureScheduleEditor();$('#scheduleStart').value=state.schedule.startTime;$('#scheduleEnd').value=state.schedule.endTime;$('#scheduleEditOverlay').classList.add('open')}
async function saveSchedule(){const start=$('#scheduleStart').value,end=$('#scheduleEnd').value;if(!start||!end)return toast('출근/퇴근 시간을 입력해주세요.');try{state.schedule=await api('/api/attendance/work-schedule',{method:'PUT',body:JSON.stringify({startTime:start,endTime:end})});refreshScheduleLabels();$('#scheduleEditOverlay').classList.remove('open');toast('근무시간이 저장되었습니다.')}catch(e){toast(e.message)}}
function bindSchedule(){const wt=$('.work-time');if(wt){wt.onclick=openSchedule;wt.setAttribute('title','근무시간 수정')}const cal=$('#scheduleBtn');if(cal)cal.onclick=openSchedule}
function getGpsFast(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('이 기기에서 GPS를 사용할 수 없습니다.'));let done=false;const timer=setTimeout(()=>{if(done)return;done=true;reject(new Error('GPS 응답 시간이 초과되었습니다. 위치서비스를 켜고 다시 시도해주세요.'))},8000);navigator.geolocation.getCurrentPosition(p=>{if(done)return;done=true;clearTimeout(timer);resolve({lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,capturedAt:new Date().toISOString()})},e=>{if(done)return;done=true;clearTimeout(timer);const msg=e.code===1?'위치 권한이 차단되어 있습니다. 브라우저 설정에서 위치 권한을 허용해주세요.':e.code===2?'현재 위치를 확인할 수 없습니다. GPS를 켠 뒤 다시 시도해주세요.':'GPS 응답 시간이 초과되었습니다. 다시 시도해주세요.';reject(new Error(msg))},{enableHighAccuracy:false,timeout:7000,maximumAge:30000})})}
function gpsLine(msg,kind=''){let el=$('#gpsFixLine');if(!el){el=document.createElement('div');el.id='gpsFixLine';el.className='gps-row-fix';const place=$('#placeCard');if(place)place.insertAdjacentElement('beforebegin',el)}if(el){el.className='gps-row-fix'+(kind?' '+kind:'');el.textContent=msg}}
async function refreshToday(){try{state.today=await api('/api/attendance/today-v2')}catch(_){state.today=null}refreshScheduleLabels()}
function patchClockButtons(){const inBtn=$('#clockInBtn'),outBtn=$('#clockOutBtn');if(!inBtn||!outBtn)return;inBtn.onclick=async()=>{if(state.today?.clockIn)return;const workplace=localStorage.getItem('namo_workplace_v4_live')||'chungju';inBtn.classList.add('loading');inBtn.disabled=true;gpsLine('GPS 위치를 확인하는 중입니다…');try{const gps=await getGpsFast();gpsLine(`GPS 확인 완료 · 오차 약 ${Math.round(gps.accuracy||0)}m`,'ok');state.today=await api('/api/attendance/clock-in-v2',{method:'POST',body:JSON.stringify({gps,device:navigator.userAgent,workplaceCode:workplace})});toast('출근 등록이 완료되었습니다.');location.reload()}catch(e){gpsLine(e.message,'error');toast(e.message);inBtn.disabled=false}finally{inBtn.classList.remove('loading')}};outBtn.onclick=async()=>{if(!state.today?.clockIn)return toast('먼저 출근을 등록해 주세요.');if(state.today?.clockOut)return;outBtn.classList.add('loading');outBtn.disabled=true;gpsLine('GPS 위치를 확인하는 중입니다…');try{const gps=await getGpsFast();gpsLine(`GPS 확인 완료 · 오차 약 ${Math.round(gps.accuracy||0)}m`,'ok');state.today=await api('/api/attendance/clock-out-v2',{method:'POST',body:JSON.stringify({gps})});toast('퇴근 등록이 완료되었습니다.');location.reload()}catch(e){gpsLine(e.message,'error');toast(e.message);outBtn.disabled=false}finally{outBtn.classList.remove('loading')}}}
async function renderFixedRecords(){const root=$('.page[data-page="records"] .records');if(!root)return;try{const month=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit'}).format(new Date());const rows=await api(`/api/attendance/logs?month=${encodeURIComponent(month)}`);const startMin=mins(state.schedule.startTime);let normal=0,late=0,incomplete=0;for(const r of rows){if(!r.clockIn)incomplete++;else{const d=new Date(r.clockIn);const mm=d.getHours()*60+d.getMinutes();if(mm>startMin+5)late++;else normal++;if(r.clockIn&&!r.clockOut)incomplete++}}const stats=$$('.page[data-page="records"] .stat');if(stats[0]){stats[0].querySelector('.s1').textContent='정상근무';stats[0].querySelector('.s2').textContent=normal}if(stats[1]){stats[1].querySelector('.s1').textContent='지각';stats[1].querySelector('.s2').textContent=late}if(stats[2]){stats[2].querySelector('.s1').textContent='미완료';stats[2].querySelector('.s2').textContent=incomplete}root.innerHTML=rows.length?rows.map(r=>{const d=safeDate(r.workDate);const days=['일','월','화','수','목','금','토'];const label=d?`${d.getMonth()+1}월 ${d.getDate()}일 (${days[d.getDay()]})`:'날짜 확인 필요';const cin=r.clockIn?new Date(r.clockIn):null;const m=cin?cin.getHours()*60+cin.getMinutes():0;let st='정상근무',cls='green';if(!r.clockIn){st='미체크';cls='gray'}else if(!r.clockOut){st='근무중';cls='blue'}else if(m>startMin+5){st='지각';cls='yellow'}return`<div class="record"><span class="dot ${cls==='green'?'green':cls==='yellow'?'yellow':''}"></span><div><div class="rdate">${label}</div><div class="rmeta"><span>출근 <b>${time(r.clockIn)}</b></span><span>퇴근 <b>${time(r.clockOut)}</b></span></div></div><span class="badge ${cls}">${st}</span></div>`}).join(''):'<div class="notice">출퇴근 기록이 없습니다.</div>'}catch(e){toast(e.message)}}
function polishLeaveTypes(){const root=$('#typeOverlay');if(!root)return;$$('.type-item',root).forEach(b=>{const raw=b.textContent.replace('›','').trim();const span=b.querySelector('span');if(span)span.textContent='›';b.setAttribute('aria-label',raw)})}
function observeRecords(){const rec=$('.page[data-page="records"] .records');if(!rec)return;let busy=false;new MutationObserver(()=>{if(busy)return;busy=true;setTimeout(()=>{renderFixedRecords().finally(()=>busy=false)},120)}).observe(rec,{childList:true,subtree:true})}
function bindRecordNav(){const b=$('.nav-btn[data-page-target="records"]');if(b)b.addEventListener('click',()=>setTimeout(renderFixedRecords,220),true)}
async function init(){await new Promise(r=>setTimeout(r,900));ensureScheduleEditor();await Promise.all([loadSchedule(),refreshToday()]);bindSchedule();patchClockButtons();polishLeaveTypes();bindRecordNav();renderFixedRecords();observeRecords()}
init();
})();
